import{_ as a,C as i,o as n,c as r,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"Digital Employees Need Pause-Preserving Budget Admission, Not Hard-Stop Semantics","description":"","frontmatter":{"title":"Digital Employees Need Pause-Preserving Budget Admission, Not Hard-Stop Semantics","date":"2026-08-08","column":"digital-employee","category":"daily","summary":"Budget exhaustion should not collapse into failure or termination. For long-running Digital Employees, the safer runtime semantics are to block new generative work, preserve accepted state, allow narrowly scoped settlement, and resume only after an authorized budget-policy change.","item_id":"Q-20260808-01","source_research_object":"research/analysis/Q-20260808-01-pause-preserving-budget-admission.md","source_reading_result":"research/reading/Q-20260808-01-session-budget-governance.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-08-pause-preserving-budget-admission-cover-v2.jpg"},"headers":[],"relativePath":"en/digital-employee/2026-08-08-pause-preserving-budget-admission.md","filePath":"en/digital-employee/2026-08-08-pause-preserving-budget-admission.md","lastUpdated":1787407830000}'),d={name:"en/digital-employee/2026-08-08-pause-preserving-budget-admission.md"};function l(c,e,u,h,g,p){const t=i("ArticleCover");return n(),r("div",null,[o(t,{image:"/assets/covers/daily-2026-08-08-pause-preserving-budget-admission-cover-v2.jpg",kicker:"Digital Employee · Daily Research",title:"Digital Employees Need Pause-Preserving Budget Admission, Not Hard-Stop Semantics",summary:"Budget exhaustion should not collapse into failure or termination. For long-running Digital Employees, the safer runtime semantics are to block new generative work, preserve accepted state, allow narrowly scoped settlement, and resume only after an authorized budget-policy change.",version:"Q-20260808-01",status:"Daily Runtime V5 · 2026-08-08",languageHref:"/zh/digital-employee/2026-08-08-pause-preserving-budget-admission",languageLabel:"中文"}),e[0]||(e[0]=s(' # Digital Employees Need Pause-Preserving Budget Admission, Not Hard-Stop Semantics <p>Once a Digital Employee owns long-running, recoverable work, a budget is no longer just a reporting number. It becomes an authority boundary that determines whether the runtime may admit the next unit of model work.</p><h2 id="central-judgment" tabindex="-1">Central judgment <a class="header-anchor" href="#central-judgment" aria-label="Permalink to &quot;Central judgment&quot;">​</a></h2><p>The safer interpretation of budget exhaustion is neither <code>failed</code> nor immediate termination. It is a <strong>reversible work-admission state</strong>: new generative requests stop entering the runtime, already accepted work state remains durable, narrowly scoped settlement may continue, and execution resumes only when an authorized policy owner changes the budget.</p><p>This conclusion is produced from the <code>Q-20260808-01</code> Research Object. Production did not reopen the Signal Pool or perform new analysis from the Reading Result.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>The sole analytical input is <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260808-01-pause-preserving-budget-admission.md" target="_blank" rel="noreferrer">Research Object — Pause-Preserving Budget Admission</a>. The Reading Result is cited only as the provenance path already declared by that object.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The Research Object separates several states that are easy to collapse in an operator UI: budget policy, exact enforcement accounting, rounded operator-facing usage, admission of new work, settlement of already-admitted obligations, and the durable state of the long-lived job.</p><p>That distinction changes the meaning of a “hard budget.” It can be a hard gate on <strong>admitting new model requests</strong> without being proof of an exact final invoice ceiling, because work admitted before the gate can still settle afterward. Likewise, a budget pause preserves job identity and history. It is neither business completion nor execution failure.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Runtime semantic</th><th style="text-align:right;">New generative work</th><th style="text-align:right;">Durable work state</th><th style="text-align:right;">Narrow settlement</th><th style="text-align:right;">Authorized resume</th></tr></thead><tbody><tr><td>Running</td><td style="text-align:right;">Allowed</td><td style="text-align:right;">Preserved</td><td style="text-align:right;">Allowed</td><td style="text-align:right;">Not required</td></tr><tr><td>BudgetPaused</td><td style="text-align:right;">Blocked</td><td style="text-align:right;">Preserved</td><td style="text-align:right;">Allowed</td><td style="text-align:right;">Required</td></tr><tr><td>Failed</td><td style="text-align:right;">Blocked</td><td style="text-align:right;">Implementation-dependent</td><td style="text-align:right;">Usually blocked</td><td style="text-align:right;">Recovery path</td></tr><tr><td>Completed</td><td style="text-align:right;">Blocked</td><td style="text-align:right;">Preserved</td><td style="text-align:right;">No new work expected</td><td style="text-align:right;">Not applicable</td></tr></tbody></table><p>This table is a Research Center synthesis from the Research Object; it does not claim that the source product exposes an identical named state machine.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>The important engineering mechanism is not budget display. It is the conversion of economic authority into a runtime admission decision. Budget policy should attach to the long-lived WorkOrder or equivalent job identity, and only an explicit policy owner should be able to change it. A worker retry, reconnect, or model-generated assertion must not silently reopen paused work.</p><p>Exact enforcement accounting should also remain distinct from rounded operator display. The Research Object explicitly preserves this boundary: a visible usage number may be approximate, while the admission gate must rely on the enforcement quantity. Promising an absolute final spend ceiling would exceed the current evidence.</p><p>Shared session budgets introduce another governance gap. If several threads share one cap, the mechanism does not automatically provide role-, department-, or task-level accountability. Those higher-level economic controls need their own policy objects.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>For Digital Employee runtimes, separate <code>Active</code>, <code>BudgetPaused</code>, <code>WaitingForAuthority</code>, and <code>Completed</code>. Persist policy owner, enforcement usage, display usage, pause reason, and resume authorization separately, and keep a narrow allowlist for settlement actions that close already-started obligations.</p><p>For CodeFlowMu, this should first appear in Runtime and WorkOrder state plus observation surfaces, not as a protocol expansion derived from one product mechanism. Recovery should reopen execution from accepted durable state rather than depend on the original provider session remaining alive.</p><h2 id="boundaries-and-counter-evidence" tabindex="-1">Boundaries and counter-evidence <a class="header-anchor" href="#boundaries-and-counter-evidence" aria-label="Permalink to &quot;Boundaries and counter-evidence&quot;">​</a></h2><p>The evidence does not establish an exact final-cost ceiling, invoice alignment between list cost and negotiated spend, per-thread budget partitioning, exactly-once event delivery, reconnect guarantees, or organization-wide cumulative budgeting.</p><p>The claim here is therefore narrower: <strong>budget should govern work admission</strong>. A single budget field is not sufficient evidence for complete enterprise cost governance.</p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>The next useful test is a minimal budget-state contract separating cap, exact consumed amount, displayed amount, settlement authority, and resume authority. It should also test composition of role budgets with a shared WorkOrder cap, crash recovery of <code>BudgetPaused</code>, settlement receipts, and operator decision UX.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The diagram models <code>Active → Budget Gate → BudgetPaused → Settlement Drain → Authorized Resume</code>. It is a Research Center synthesis based on the cited Research Object and does not imply unsupported quantitative results.</p><h2 id="evidence-and-references" tabindex="-1">Evidence and references <a class="header-anchor" href="#evidence-and-references" aria-label="Permalink to &quot;Evidence and references&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260808-01-pause-preserving-budget-admission.md" target="_blank" rel="noreferrer">Research Object — Pause-Preserving Budget Admission</a>: sole analytical input for Production, including judgment, uncertainty, counter-evidence, and engineering impact.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260808-01-session-budget-governance.md" target="_blank" rel="noreferrer">Reading Result — Session Budget Governance</a>: provenance path declared by the Research Object; Production did not perform new research from it.</li></ol>',29))])}const y=a(d,[["render",l]]);export{b as __pageData,y as default};
